export type IRuntime = {
  readonly [RUNTIME_BRAND]: true;
  /** * Creates a writable node owned by this runtime and sharing its dependency graph and version * clock. */ signal<
    T,
  >(
    value: T,
    options?: IReactiveNodeOptions,
  ): IReactiveSignal<T>;
  computed<T>(fn: () => T, config?: IComputedConfig<T>): IReactiveComputed<T>;
  /** Creates an immediately executed effect whose handle owns idempotent disposal. */ effect(
    fn: () => void | IDisposer,
    options?: IReactiveNodeOptions,
  ): IReactiveEffect;
  batch<T>(fn: () => T): T;
  untracked<T>(fn: () => T): T;
  /** * Flushes synchronously. Reentrant observer calls return `deferred`; the outer call returns * `completed` after draining the queue. */ flush(): IFlushResult;
  /** * Runs and traces an action. Callers provide only its name and function, never fabricated phases * or trace events. */ runTracedAction<
    T,
  >(
    name: string,
    fn: () => T,
  ): T;
  reportError(error: unknown, context: IRuntimeErrorReportContext): void;
  /** * Subscribes to read-only diagnostics. Only the trusted kernel emits action and dependency * records. */ subscribeTrace(
    listener: (event: IRuntimeTraceEvent) => void,
  ): IDisposer;
};

