  /** * An atom preview cycle is detected within one render or preview stack. * * Check derived dependencies for cycles. */ readonly circularPreview: 'CIRCULAR_PREVIEW';
  /** * An atom override chain contains a cycle and cannot resolve its final definition. * * Check whether override targets point back to each other. */ readonly cyclicOverride: 'CYCLIC_OVERRIDE';
