  ): T;
  /** React/concurrent speculative read; value may be discarded after the turn. */ preview<
    T,
  >(
    definition: IAtomDefinition<T>,
  ): T;
  set<T, Args extends readonly unknown[], Result>(
    definition: IWritableAtomDefinition<T, Args, Result>,
    ...args: Args
  ): Result;
  /** * Subscribes to a definition and returns an unsubscribe function. * * Adapters subscribe through this boundary instead of accessing graph nodes, leaving * instantiation strategies independent. */ sub<
    T,
  >(
    definition: IAtomDefinition<T>,
    onChange: () => void,
  ): IDisposer;
  /** Routes a read-only derived definition to any definition with the same value type. */ override<
    T,
  >(
    definition: IDerivedDefinition<T>,
