const audit: IStoreMiddlewarePlugin<AppState> = {
  name: 'audit',
  install: (core) => {
    core.usePipeline((event, next) => {
      next(event);
      if (event.type === 'action' && event.phase === 'end') {
        auditSink({ action: event.name, state: core.getState() });
      }
    });
    return {};
  }
};

