import { TRAY_SOURCE, TrayErrorCode, type ITrayGraph, type ITrayKey } from '@migaia/tray'

/** 读取已有 Graph 的值，并按公开错误码处理不可用状态。 */
function readApi(tray: ITrayGraph, apiKey: ITrayKey): unknown {
  try {
    return tray.get(apiKey)
  } catch (error) {
